'use strict';

// MODULES //

var erf = require( '@stdlib/math/base/special/erf' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Evaluates the cumulative distribution function (CDF) for a half-normal distribution with scale parameter `sigma` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} sigma - scale parameter
* @returns {Probability} evaluated cumulative distribution function
*
* @example
* var y = cdf( 2.0, 1.0 );
* // returns 0.9544997361036416
*
* @example
* var y = cdf( -1.0, 2.0 );
* // returns 0.0
*
* @example
* var y = cdf( 0.0, 1.0 );
* // returns 0.0
*
* @example
* var y = cdf( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = cdf( 0.0, NaN );
* // returns NaN
*
* @example
* // Negative scale parameter:
* var y = cdf( 2.0, -1.0 );
* // returns NaN
*/
function cdf( x, sigma ) {
	var denom;
	if (
		isnan( x ) ||
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return NaN;
	}
	if ( x < 0.0 ) {
		return 0.0;
	}
	if ( sigma === 0.0 ) {
		return ( x >= 0.0 ) ? 1.0 : 0.0;
	}
	denom = sigma * sqrt( 2.0 );
	return erf( x / denom );
}


// EXPORTS //

module.exports = cdf;
